def dimensions_square_feet(value: Any) -> float:
    """Return square feet for the first width x height pair in an item dimension.

    Effects: Performs a calculation only; no database or file state is changed.
    Flow: Accepts common whole, decimal, and mixed-fraction inch formats such as
    ``36 x 72`` or ``36 1/2 x 72 3/4`` and returns zero when the dimensions are
    incomplete. Reporting callers can therefore track missing-dimension coverage
    instead of inventing an area.
    """
    text = str(value or "").strip().replace("×", "x")
    parts = re.split(r"\s*[xX]\s*", text, maxsplit=1)
    if len(parts) < 2:
        return 0.0

    def dimension_value(part: str) -> float:
        cleaned = re.sub(r"(?<=\d)-(?=\d+\s*/\s*\d+)", " ", str(part or ""))
        cleaned = cleaned.replace('"', " ").replace("inches", " ").replace("inch", " ").replace("in", " ")
        match = re.search(r"\d+(?:\.\d+)?(?:\s+\d+\s*/\s*\d+)?|\d+\s*/\s*\d+", cleaned)
        if not match:
            return 0.0
        return parse_dimension_number(re.sub(r"\s*/\s*", "/", match.group(0)))

    width = dimension_value(parts[0])
    height = dimension_value(parts[1])
    if width <= 0 or height <= 0:
        return 0.0
    return (width * height) / 144.0


def canonical_clear_glass_label(value: Any) -> str:
    """Return an explicit heat-treatment identity for clear glass.

    v0.460 operational rule: clear glass must always resolve to either Tempered
    or Annealed. Historical/imported clear labels that omit both words are
    treated as Annealed. Mirror labels are intentionally excluded, and source
    text is never rewritten in the database.
    """
    raw = " ".join(str(value or "").split()).strip()
    if not raw:
        return ""
    if re.search(r"\bmirror\b", raw, flags=re.IGNORECASE):
        return raw
    if not re.search(r"(?:\bclear\b|\bultra\s*clear\b)", raw, flags=re.IGNORECASE):
        return raw

    tempered = bool(re.search(r"\b(?:temper(?:ed)?|temp|toughened)\b", raw, flags=re.IGNORECASE))
    base = re.sub(r"\b(?:temper(?:ed)?|temp|toughened|anneal(?:ed)?|ann)\b", " ", raw, flags=re.IGNORECASE)
    base = " ".join(base.split()).strip()
    if not base:
        base = raw
    # Explicit Tempered wins when conflicting legacy text contains both tokens;
    # otherwise explicit or implicit non-tempered clear glass is Annealed.
    treatment = "Tempered" if tempered else "Annealed"
    return f"{base} {treatment}".strip()


def glass_profile_identity_key(value: Any) -> str:
    """Return the stable physical-profile identity used by Lookup Manager.

    v0.461 keeps persisted glass aliases reversible across restarts and older
    releases. Alias targets can predate later display normalization (for example
    ``3/8 Clear`` versus ``3/8 Clear Annealed``), so uncombine compares this
    normalized identity instead of depending on the target label text remaining
    byte-for-byte unchanged forever.
    """
    raw = " ".join(str(value or "").split()).strip()
    if not raw:
        return ""
    treatment_pattern = r"\b(?:temper(?:ed)?|temp|toughened|anneal(?:ed)?|ann)\b"
    if re.search(r"\bmirror\b", raw, flags=re.IGNORECASE):
        canonical = re.sub(treatment_pattern, " ", raw, flags=re.IGNORECASE)
        canonical = " ".join(canonical.split()).strip()
    else:
        tempered = bool(re.search(r"\b(?:temper(?:ed)?|temp|toughened)\b", raw, flags=re.IGNORECASE))
        base = re.sub(treatment_pattern, " ", raw, flags=re.IGNORECASE)
        base = " ".join(base.split()).strip()
        canonical = f"{base or raw} {'Tempered' if tempered else 'Annealed'}".strip()
    return re.sub(r"[^A-Z0-9]+", "", canonical.upper())


def glass_cost_profile(
    value: Any,
    pricing: dict[str, float] | None = None,
    aliases: dict[str, str] | None = None,
) -> tuple[str, float | None]:
    """Resolve one product label to the effective glass-cost reference.

    Effects: Performs an in-memory lookup only.
    Flow: Matches the longest normalized configured label inside the imported
    product text so harmless suffixes such as process wording do not prevent a
    match. Callers may supply the administrator-maintained effective price map;
    otherwise the built-in defaults remain the safe fallback. Unknown glass is
    preserved by name and returned without a price so reporting can disclose the
    coverage gap rather than silently estimate it.
    """
    raw = " ".join(str(value or "").split()).strip() or "Other Glass"
    cost_map = pricing if isinstance(pricing, dict) else GLASS_COST_PER_SQFT

    # v0.360: explicit administrator combinations resolve exact imported names
    # to one canonical glass identity without rewriting historical line items.
    resolved = raw
    if isinstance(aliases, dict) and aliases:
        alias_map = {" ".join(str(key or "").split()).lower(): " ".join(str(target or "").split()).strip() for key, target in aliases.items()}
        visited: set[str] = set()
        for _depth in range(12):
            key = resolved.lower()
            if not key or key in visited:
                break
            visited.add(key)
            target = alias_map.get(key)
            if not target or target.lower() == key:
                break
            resolved = target

    # v0.460: normalize clear-glass heat treatment after administrator aliases
    # resolve. This makes Statistics and every backend reporting surface use the
    # same explicit Annealed/Tempered identity as the operator interfaces.
    resolved = canonical_clear_glass_label(resolved) or resolved
    normalized = re.sub(r"[^A-Z0-9]+", "", resolved.upper())
    candidates = sorted(
        cost_map.items(),
        key=lambda entry: len(re.sub(r"[^A-Z0-9]+", "", entry[0].upper())),
        reverse=True,
    )
    for label, rate in candidates:
        key = re.sub(r"[^A-Z0-9]+", "", label.upper())
        if key and key in normalized:
            # Preserve an administrator-selected alias target and the explicit
            # clear-glass heat treatment. For ordinary products, retain the
            # configured cost-profile label just as the existing resolver did.
            matched_label = canonical_clear_glass_label(label) or label
            if resolved.lower() != raw.lower():
                return resolved, float(rate)
            return matched_label, float(rate)
    return resolved, None


def route_signal_text(item: dict[str, Any]) -> str:
    """Purpose: Run the route signal text workflow for the delivery-list scanner.

    Effects: This function reads or updates shared application state.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    return " ".join(
        str(item.get(key, ""))
        for key in ("route", "job", "customer", "product", "processState", "queueState")
    ).upper()


ROUTE_GREENVILLE_ALIASES = {
    "GNV",
    "GRN",
    "GRVLLE",
    "GRVILLE",
    "GRVLE",
    "GVLLE",
    "GREENVILLE",
}
ROUTE_CPU_INDIAN_TRAIL_COMPACT = {"CPUIT", "CPUINT", "ITCPU", "INTCPU"}
ROUTE_CPU_AIR_COMPACT = {"CPUAIR", "AIRCPU"}
ROUTE_STAGE_REPAIR_VERSION = "v060-customer-route-primary-1"


def cpu_job_route_hint(value: Any) -> str | None:
    """Return the only supported Job Nr. destination overrides.

    CPU-Air sends the item to Customer Pickup. CPU-IT/CPU-INT explicitly keeps
    the item on the Indian Trail route. DTC and Greenville are intentionally
    not inferred from Job Nr.; active Customer Route Rules own those routes.
    """
    text = str(value or "").strip().upper()
    if not text:
        return None
    compact = normalized_match_text(text)
    separator = r"[^A-Z0-9]*"
    token_start = r"(?:^|[^A-Z0-9])"
    token_end = r"(?![A-Z0-9])"
    cpu_indian_trail = re.compile(
        rf"(?:{token_start}CPU{separator}(?:IT|INT){token_end}|"
        rf"{token_start}(?:IT|INT){separator}CPU{token_end})"
    )
    cpu_air = re.compile(
        rf"(?:{token_start}CPU{separator}AIR{token_end}|"
        rf"{token_start}AIR{separator}CPU{token_end})"
    )
    if compact in ROUTE_CPU_INDIAN_TRAIL_COMPACT or cpu_indian_trail.search(text):
        return ""
    if compact in ROUTE_CPU_AIR_COMPACT or cpu_air.search(text):
        return "CPU"
    return None


def canonical_route_designation(value: Any, *, job_context: bool = False) -> tuple[bool, str]:
    """Resolve an operational route designation to the stored route code.

    Route values and Job Nr. suffixes are typed by people, so matching accepts
    capitalization and separator differences while retaining strict token
    boundaries. In Job Nr. context, only CPU-Air and CPU-IT/INT are treated as
    destination overrides; DTC and Greenville come from Customer Route Rules.
    """
    text = str(value or "").strip().upper()
    if not text:
        return False, ""

    compact = normalized_match_text(text)
    token_start = r"(?:^|[^A-Z0-9])"
    token_end = r"(?![A-Z0-9])"

    cpu_hint = cpu_job_route_hint(text)
    if cpu_hint is not None:
        return True, cpu_hint
    if job_context:
        return False, ""

    if compact in {"DTC", "DELIVERTOCUSTOMER"} or re.search(
        rf"{token_start}DTC{token_end}",
        text,
    ):
        return True, "DTC"

    if compact in ROUTE_GREENVILLE_ALIASES or any(
        re.search(rf"{token_start}{re.escape(alias)}{token_end}", text)
        for alias in ROUTE_GREENVILLE_ALIASES
    ):
        return True, "GNV"

    if compact in {"CUSTOMERPICKUP", "PICKUP"}:
        return True, "CPU"

    if compact == "CPU" or re.search(rf"{token_start}CPU{token_end}", text):
        return True, "CPU"
    if compact in {"INT", "IT", "INDIANTRAIL"}:
        return True, ""
    return False, ""


def normalize_route_column(value: Any) -> tuple[bool, str]:
    """Return whether ROUTE was supplied and its canonical route code."""
    route = str(value or "").strip().upper()
    if not route:
        return False, ""
    matched, canonical = canonical_route_designation(route)
    return (True, canonical) if matched else (True, route)


def job_number_route_hint(item: dict[str, Any]) -> str | None:
    """Return the supported CPU-Air/CPU-IT override from Job Nr."""
    return cpu_job_route_hint(item.get("job", ""))


def inferred_route(item: dict[str, Any]) -> str:
    """Purpose: Run the inferred route workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    raw_route = str(item.get("route", "")).strip()
    explicit, route = normalize_route_column(raw_route)
    job_hint = job_number_route_hint(item)
    if explicit:
        # Imports historically stored the fallback Indian Trail value as IT.
        # A strong DTC, Greenville, or CPU-Air Job Nr. designation repairs that
        # generated fallback while an explicitly written Indian Trail phrase or
        # CPU-IT designation remains Indian Trail.
        if normalized_match_text(raw_route) == "IT" and job_hint in {"CPU", "GNV", "DTC"}:
            return job_hint
        return route

    if job_hint is not None:
        return job_hint

    customer_route = default_customer_route(item)
    if customer_route:
        return normalize_route_column(customer_route)[1]

    # Generic CPU text in Job Nr. remains Indian Trail unless an explicit ROUTE
    # or customer-route rule says otherwise.
    return ""


def route_category(item: dict[str, Any]) -> str:
    """Purpose: Run the route category workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    route = inferred_route(item)
    if route == "CPU":
        return "cpu"
    if route == "GNV":
        return "greenville"
    if route == "DTC":
        return "dtc"
    if route:
        return f"custom:{route}"
    return "indian_trail"


def custom_route_codes(base_items: list[dict[str, Any]]) -> list[str]:
    """Purpose: Run the custom route codes workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    codes = {
        inferred_route(item)
        for item in base_items
        if route_category(item).startswith("custom:")
    }
    return sorted(code for code in codes if code)


def route_stage_label(route: str) -> str:
    """Return the active display name for a route-backed delivery stage.

    v0.346 first consults the Stage Editor cache so route/stage presentation may
    be renamed without rewriting operational preset logic. Fallback aliases keep
    old databases and offline verification scripts compatible.
    """
    clean = str(route or "").strip().upper()
    aliases = {"GRN": "GNV", "GREENVILLE": "GNV"}
    canonical = aliases.get(clean, clean)
    for definition in _STAGE_DEFINITION_CACHE:
        route_code = str(definition.get("routeCode") or "").strip().upper()
        if route_code and route_code == canonical:
            return str(definition.get("displayName") or canonical).strip() or canonical
    if canonical == "CPU":
        return "Customer Pickup"
    if canonical == "DTC":
        return "Delivery to Customer"
    if canonical == "GNV":
        return "BFS Greenville"
    return canonical


def public_route_label(value: Any) -> str:
    """Return the route label that may appear on printed or exported documents.

    Effects: Does not modify the stored route. Standard Indian Trail designations are
    intentionally hidden so exception routes such as CPU, DTC, Greenville, and custom
    destinations remain visually meaningful on floor paperwork and exported files.
    Flow: Canonicalizes common operational aliases, returns an empty label for the
    standard Indian Trail route, and preserves nonstandard/custom route text.
    """
    raw = str(value or "").strip()
    if not raw:
        return ""
    matched, canonical = canonical_route_designation(raw)
    if matched:
        if canonical == "":
            return ""
        return canonical
    return raw


def receiving_stage_destination(stage: Any, scanner: Any = "") -> str:
    """Return the destination implied by a configured stage behavior preset."""
    preset = stage_logic_preset(stage, scanner)
    if preset in STAGE_PRESET_CATALOG:
        destination = STAGE_PRESET_CATALOG[preset].get("destination", "")
        if destination:
            return destination
    text = f"{stage or ''} {scanner or ''}".strip().lower()
    if "indian trail" in text or "inbound" in text:
        return "Indian Trail"
    if "customer pickup" in text or re.search(r"\bcpu\b", text):
        return "CPU"
    if "greenville" in text or re.search(r"\bgnv\b", text):
        return "Greenville"
    if "deliver to customer" in text or re.search(r"\bdtc\b", text):
        return "DTC"
    return ""


def scan_stage_category(stage: Any, scanner: Any = "") -> str:
    """Return the operational scan category, honoring Stage Editor presets first."""
    preset = stage_logic_preset(stage, scanner)
    if preset in STAGE_PRESET_CATALOG:
        return STAGE_PRESET_CATALOG[preset].get("category", "staged")
    text = f"{stage or ''} {scanner or ''}".strip().lower()
    if "outbound" in text:
        return "outbound"
    if "dtc" in text or "deliver to customer" in text:
        return "dtc"
    if "greenville" in text or re.search(r"\bgnv\b", text):
        return "greenville"
    if "indian trail" in text or "inbound" in text:
        return "received"
    if "customer pickup" in text or re.search(r"\bcpu\b", text):
        return "pickup"
    return "staged"


def is_cpu_item(item: dict[str, Any]) -> bool:
    """Purpose: Validate CPU item for the delivery-list scanner workflow.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    return route_category(item) == "cpu"


def normalized_bay_auto_assign_settings(settings: dict[str, Any] | None = None) -> dict[str, Any]:
    """Purpose: Run the normalized bay auto assign settings workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Validates the supplied value, normalizes supported formats, and returns a predictable representation.
    """
    merged = dict(DEFAULT_BAY_AUTO_ASSIGN_SETTINGS)
    if isinstance(settings, dict):
        merged.update(settings)
    for key in ("standardMaxInches", "tallMinInches", "oversizeMinInches"):
        try:
            merged[key] = float(merged.get(key, DEFAULT_BAY_AUTO_ASSIGN_SETTINGS[key]))
        except (TypeError, ValueError):
            merged[key] = float(DEFAULT_BAY_AUTO_ASSIGN_SETTINGS[key])
    manual = merged.get("manualAssignTypes")
    if isinstance(manual, str):
        manual = [value.strip() for value in manual.split(",") if value.strip()]
    if not isinstance(manual, list):
        manual = list(DEFAULT_BAY_AUTO_ASSIGN_SETTINGS["manualAssignTypes"])
    merged["manualAssignTypes"] = [str(value).strip() for value in manual if str(value).strip()]
    return merged


def suggested_bay(product: str, dimensions: str, route: str, settings: dict[str, Any] | None = None) -> str:
    """Purpose: Run the suggested bay workflow for the delivery-list scanner.

    Effects: This function reads or updates shared application state.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    config = normalized_bay_auto_assign_settings(settings)
    if str(route).upper() == "CPU":
        return str(config.get("cpuBayType") or "CPU")
    product_text = str(product or "").upper()
    if "FRAMED" in product_text and "MIRROR" in product_text:
        return str(config.get("framedMirrorBayType") or "Framed Mirror")
    if "MIRROR" in product_text:
        return str(config.get("mirrorBayType") or "Mirror")
    parts = re.findall(r"\d+(?:\s+\d+/\d+|/\d+)?", str(dimensions))
    largest = max([parse_dimension_number(part) for part in parts] or [0])
    if largest >= float(config.get("oversizeMinInches") or 96):
        return str(config.get("oversizeBayType") or "Oversize")
    if largest >= float(config.get("tallMinInches") or 60):
        return str(config.get("tallBayType") or "Tall")
    return str(config.get("standardBayType") or "Standard")


def items_for_profile(profile: str, base_items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Purpose: Run the items for profile workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    if profile == "cpu":
        return [item for item in base_items if is_cpu_item(item)]
    if profile == "indian_trail":
        return [item for item in base_items if route_category(item) == "indian_trail"]
    if profile == "greenville":
        return [item for item in base_items if route_category(item) == "greenville"]
    if profile == "dtc":
        return [item for item in base_items if route_category(item) == "dtc"]
    if profile.startswith("route:"):
        route = profile.split(":", 1)[1].upper()
        return [item for item in base_items if inferred_route(item) == route]
    return list(base_items)


def build_delivery_lists(sample: dict[str, Any]) -> list[tuple[str, str, str, str, list[dict[str, Any]]]]:
    """Purpose: Build delivery lists for the delivery-list scanner workflow.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Applies access and lookup rules, gathers the relevant records, and returns a caller-ready result.
    """
    delivery_date = str(sample.get("deliveryDate") or now_iso()[:10])
    base_items = sample.get("items") or []
    definitions: list[tuple[str, str, str, str, list[dict[str, Any]]]] = []
    configured_route_codes: set[str] = set()
    for definition in stage_definitions():
        suffix = str(definition.get("key") or "").strip()
        stage = str(definition.get("displayName") or suffix).strip()
        preset = str(definition.get("preset") or "airport_staging")
        preset_meta = STAGE_PRESET_CATALOG.get(preset, STAGE_PRESET_CATALOG["airport_staging"])
        scanner = str(definition.get("scanner") or preset_meta.get("scanner") or stage).strip()
        route_code = str(definition.get("routeCode") or "").strip().upper()
        if route_code:
            configured_route_codes.add(route_code)
        profile = stage_profile_selector(definition)
        if not suffix or (profile == "route:"):
            continue
        items = items_for_profile(profile, base_items)
        if profile != "all" and not items:
            continue
        definitions.append(
            (
                f"{delivery_date}-{suffix}",
                f"{format_display_date(delivery_date)} - {stage}",
                stage,
                scanner,
                items,
            )
        )
    for route in custom_route_codes(base_items):
        if route.upper() in configured_route_codes:
            continue
        suffix = f"route-{re.sub(r'[^a-z0-9]+', '-', route.lower()).strip('-')}"
        stage = route_stage_label(route)
        items = items_for_profile(f"route:{route}", base_items)
        if not items:
            continue
        definitions.append(
            (
                f"{delivery_date}-{suffix}",
                f"{format_display_date(delivery_date)} - {stage}",
                stage,
                stage,
                items,
            )
        )
    return definitions


def all_profile_list_ids(delivery_date: str) -> list[str]:
    """Purpose: Run the all profile list IDs workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Applies access and lookup rules, gathers the relevant records, and returns a caller-ready result.
    """
    return [f"{delivery_date}-{definition['key']}" for definition in stage_definitions() if definition.get("key")]


def parse_int_text(value: Any) -> int | None:
    """Purpose: Parse int text for the delivery-list scanner workflow.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Validates the supplied value, normalizes supported formats, and returns a predictable representation.
    """
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return int(float(text.replace(",", "")))
    except ValueError:
        match = re.search(r"\d+", text)
        return int(match.group(0)) if match else None


def clean_excel_text(value: Any) -> str:
    """Purpose: Run the clean excel text workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    text = str(value or "")
    text = re.sub(r"_x000[dD]_", "\r", text)
    text = re.sub(r"_x000[aA]_", "\n", text)
    return re.sub(r"\s+", " ", text.replace("\r", " ").replace("\n", " ")).strip()


def format_delivery_date(month: int, day: int, year: int) -> str:
    """Purpose: Normalize delivery date for the delivery-list scanner workflow.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Validates the supplied value, normalizes supported formats, and returns a predictable representation.
    """
    if year < 100:
        year += 2000
    return f"{year:04d}-{month:02d}-{day:02d}"


def delivery_date_from_text(text: str) -> str:
    """Purpose: Run the delivery date from text workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    match = re.search(r"\b(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})(?!\d)", text)
    if not match:
        return ""
    month, day, year = (int(part) for part in match.groups())
    return format_delivery_date(month, day, year)


def column_label(ref: str) -> str:
    """Purpose: Run the column label workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    match = re.match(r"([A-Z]+)", ref.upper())
    return match.group(1) if match else ""


def first_xlsx_sheet_path(archive: zipfile.ZipFile) -> str:
    """Purpose: Run the first XLSX sheet path workflow for the delivery-list scanner.

    Effects: This function reads or changes files.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    try:
        workbook = ET.fromstring(archive.read("xl/workbook.xml"))
        first_sheet = workbook.find(f"{XLSX_MAIN_NS}sheets/{XLSX_MAIN_NS}sheet")
        rel_id = first_sheet.attrib.get(f"{XLSX_REL_NS}id") if first_sheet is not None else ""
        relationships = ET.fromstring(archive.read("xl/_rels/workbook.xml.rels"))
        for rel in relationships.findall(f"{XLSX_PACKAGE_REL_NS}Relationship"):
            if rel.attrib.get("Id") == rel_id:
                target = rel.attrib.get("Target", "").lstrip("/")
                return target if target.startswith("xl/") else f"xl/{target}"
    except Exception:
        pass
    for name in archive.namelist():
        if name.startswith("xl/worksheets/") and name.endswith(".xml") and "/_rels/" not in name:
            return name
    raise ValueError("Workbook does not contain a worksheet XML file")


def read_xlsx_rows(path: Path, max_rows: int | None = None) -> list[tuple[int, dict[str, str]]]:
    """Purpose: Read XLSX rows for the delivery-list scanner workflow.

    Effects: This function reads or changes files.
    Flow: Applies access and lookup rules, gathers the relevant records, and returns a caller-ready result.
    """
    with zipfile.ZipFile(path) as archive:
        shared_strings: list[str] = []
        if "xl/sharedStrings.xml" in archive.namelist():
            root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
            for item in root.findall(f"{XLSX_MAIN_NS}si"):
                shared_strings.append(clean_excel_text("".join(node.text or "" for node in item.iter(f"{XLSX_MAIN_NS}t"))))
        sheet = ET.fromstring(archive.read(first_xlsx_sheet_path(archive)))
        rows: list[tuple[int, dict[str, str]]] = []
        for row in sheet.findall(f"{XLSX_MAIN_NS}sheetData/{XLSX_MAIN_NS}row"):
            row_number = int(row.attrib.get("r") or len(rows) + 1)
            if max_rows is not None and row_number > max_rows:
                break
            values: dict[str, str] = {}
            for cell in row.findall(f"{XLSX_MAIN_NS}c"):
                col = column_label(cell.attrib.get("r", ""))
                if not col:
                    continue
                cell_type = cell.attrib.get("t")
                raw_value = ""
                if cell_type == "inlineStr":
                    raw_value = "".join(node.text or "" for node in cell.iter(f"{XLSX_MAIN_NS}t"))
                else:
                    value_node = cell.find(f"{XLSX_MAIN_NS}v")
                    raw_value = value_node.text if value_node is not None and value_node.text is not None else ""
                    if cell_type == "s" and raw_value.isdigit():
                        index = int(raw_value)
                        raw_value = shared_strings[index] if index < len(shared_strings) else ""
                value = clean_excel_text(raw_value)
                if value:
                    values[col] = value
            if values:
                rows.append((row_number, values))
        return rows


def delivery_date_from_rows_or_name(rows: list[tuple[int, dict[str, str]]], path: Path) -> str:
    """Purpose: Run the delivery date from rows or name workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    for _, row in rows[:12]:
        date_text = delivery_date_from_text(" ".join(row.values()))
        if date_text:
            return date_text
    date_text = delivery_date_from_text(path.stem)
    if date_text:
        return date_text
    return now_iso()[:10]


def delivery_date_from_source_header(path: Path) -> str:
    """Purpose: Run the delivery date from source header workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    suffix = path.suffix.lower()
    if suffix in {".xlsx", ".xlsm"}:
        try:
            rows = read_xlsx_rows(path, max_rows=12)
            return delivery_date_from_rows_or_name(rows, path)
        except Exception:
            return delivery_date_from_text(path.stem)
    if suffix == ".json":
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
            return str(payload.get("deliveryDate") or "").strip() or delivery_date_from_text(path.stem)
        except Exception:
            return delivery_date_from_text(path.stem)
    return delivery_date_from_text(path.stem)


def parse_aw_delivery_workbook(path: Path) -> dict[str, Any]:
    """Purpose: Parse aw delivery workbook for the delivery-list scanner workflow.

    Effects: This function reads or updates shared application state.
    Flow: Validates the supplied value, normalizes supported formats, and returns a predictable representation.
    """
    rows = read_xlsx_rows(path)
    delivery_date = delivery_date_from_rows_or_name(rows, path)
    current_product = ""
    items: list[dict[str, Any]] = []
    for row_number, row in rows:
        a_value = row.get("A", "")
        order_col = item_col = qty_col = dims_col = customer_col = remake_col = route_col = ""
        if parse_int_text(row.get("F")) is not None and parse_int_text(row.get("G")) is not None and parse_int_text(row.get("J")) is not None:
            order_col, item_col, qty_col, dims_col, customer_col, remake_col, route_col = "F", "G", "J", "L", "N", "V", "X"
        elif parse_int_text(row.get("E")) is not None and parse_int_text(row.get("F")) is not None and parse_int_text(row.get("G")) is not None:
            order_col, item_col, qty_col, dims_col, customer_col, remake_col, route_col = "E", "F", "G", "H", "I", "J", "L"
        else:
            header_text = " ".join(row.values()).lower()
            if a_value and "delivery list" not in header_text and "job nr" not in header_text:
                current_product = a_value
            continue

        order_no = parse_int_text(row.get(order_col))
        item_no = parse_int_text(row.get(item_col))
        qty = parse_int_text(row.get(qty_col))
        if order_no is None or item_no is None or qty is None:
            continue
        # SQL-generated v0.324 workbooks carry the immutable source Order/Item
        # in hidden Y/Z cells. Visible Order/Item may be an operator override;
        # preserving the source key prevents the next import from duplicating
        # that edited row under a new identity. Legacy workbooks simply fall
        # back to their visible Order/Item values.
        source_order_no = parse_int_text(row.get("Y"))
        source_item_no = parse_int_text(row.get("Z"))
        if source_order_no is None:
            source_order_no = order_no
        if source_item_no is None:
            source_item_no = item_no
        remake = row.get(remake_col, "")
        is_remake = is_remake_item({"processState": remake, "queueState": remake})
        item = {
            "id": f"{path.stem}:{row_number}:{source_order_no}:{source_item_no}",
            "order": str(order_no),
            "item": str(item_no).zfill(3),
            "qty": qty,
            "dimensions": row.get(dims_col, ""),
            "customer": row.get(customer_col, ""),
            "route": row.get(route_col, ""),
            "job": a_value,
            "product": current_product,
            "processState": "Remake" if is_remake else "",
            "queueState": remake,
            "sourceRow": row_number,
        }
        items.append(item)
    if not items:
        raise ValueError(f"No delivery-list rows found in {path.name}")
    return {"deliveryDate": delivery_date, "sourceName": path.name, "items": items}


def parse_delivery_csv(path: Path) -> dict[str, Any]:
    """Parse a delivery-list CSV while honoring an in-file delivery date.

    CSV exports may carry the delivery date in a column instead of the file
    name. The first valid row date is authoritative; the file name and current
    date are fallbacks for legacy files that omit it.
    """
    with path.open(newline="", encoding="utf-8-sig") as handle:
        rows = list(csv.DictReader(handle))
    delivery_date = ""
    for row in rows:
        date_value = (
            row.get("deliveryDate")
            or row.get("Delivery Date")
            or row.get("Delivery Date:")
            or row.get("delivery_date")
            or row.get("Date")
            or row.get("date")
            or ""
        )
        delivery_date = delivery_date_from_text(str(date_value))
        if delivery_date:
            break
    items = []
    for index, row in enumerate(rows, start=1):
        order_no = row.get("order") or row.get("Order Nr.") or row.get("Order Nr") or row.get("Order")
        item_no = row.get("item") or row.get("Item Nr.") or row.get("Item Nr") or row.get("Item")
        qty = row.get("qty") or row.get("Qty.") or row.get("Qty") or "1"
        if not order_no or not item_no:
            continue
        item = {
            "id": f"{path.stem}:{index}:{order_no}:{item_no}",
            "order": str(parse_int_text(order_no) or order_no),
            "item": str(parse_int_text(item_no) or item_no).zfill(3),
            "qty": parse_int_text(qty) or 1,
            "dimensions": row.get("dimensions") or row.get("Dimensions") or "",
            "customer": row.get("customer") or row.get("Customer") or "",
            "route": row.get("route") or row.get("Route") or "",
            "job": row.get("job") or row.get("Job Nr.") or row.get("Job Nr") or "",
            "product": row.get("product") or row.get("Product") or "",
            "processState": row.get("processState") or row.get("Process State") or "",
            "queueState": row.get("queueState") or row.get("Queue State") or "",
        }
        items.append(item)
    if not items:
        raise ValueError(f"No delivery-list rows found in {path.name}")
    return {
        "deliveryDate": delivery_date or delivery_date_from_text(path.stem) or now_iso()[:10],
        "sourceName": path.name,
        "items": items,
    }


def load_delivery_source_payload(path: Path) -> dict[str, Any]:
    """Purpose: Load delivery source payload for the delivery-list scanner workflow.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    suffix = path.suffix.lower()
    if suffix == ".json":
        return json.loads(path.read_text(encoding="utf-8"))
    if suffix in {".xlsx", ".xlsm"}:
        return parse_aw_delivery_workbook(path)
    if suffix == ".csv":
        return parse_delivery_csv(path)
    raise ValueError(f"Unsupported import file type: {path.suffix}")


def select_latest_delivery_source_files(paths: Iterable[Path]) -> tuple[list[Path], list[dict[str, Any]]]:
    """Choose one deterministic source workbook per delivery date.

    The Temp Delivery Lists folder can contain a manually copied A+W workbook
    beside the canonical SQL-generated workbook for the same date. Importing
    both files in filename order can apply one source and immediately overwrite
    it with the other. The newest modified file is therefore authoritative for
    a folder-import run; the canonical ``Delivery List ...`` name wins only when
    timestamps are identical. Files without a readable delivery date remain
    eligible so their normal validation error is still reported.
    """
    selected_by_date: dict[str, tuple[tuple[float, int, str], Path]] = {}
    undated: list[Path] = []
    ignored: list[dict[str, Any]] = []

    for path in sorted(paths, key=lambda value: value.name.lower()):
        try:
            delivery_date = delivery_date_from_source_header(path) or delivery_date_from_text(path.stem)
        except Exception:
            delivery_date = delivery_date_from_text(path.stem)
        if not delivery_date:
            undated.append(path)
            continue

        try:
            modified_at = float(path.stat().st_mtime)
        except OSError:
            modified_at = 0.0
        canonical_name = 1 if re.match(r"^delivery\s+list\b", path.stem, flags=re.IGNORECASE) else 0
        score = (modified_at, canonical_name, path.name.lower())
        current = selected_by_date.get(delivery_date)
        if current is None or score > current[0]:
            if current is not None:
                ignored.append({
                    "fileName": current[1].name,
                    "deliveryDate": delivery_date,
                    "reason": f"A newer source workbook was selected for {delivery_date}: {path.name}",
                })
            selected_by_date[delivery_date] = (score, path)
        else:
            ignored.append({
                "fileName": path.name,
                "deliveryDate": delivery_date,
                "reason": f"A newer source workbook was selected for {delivery_date}: {current[1].name}",
            })

    selected = undated + [record[1] for record in selected_by_date.values()]
    selected.sort(key=lambda value: value.name.lower())
    ignored.sort(key=lambda value: (str(value.get("deliveryDate") or ""), str(value.get("fileName") or "").lower()))
    return selected, ignored


def source_file_hash(path: Path) -> str:
    """Purpose: Run the source file hash workflow for the delivery-list scanner.

    Effects: This function reads or changes files.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def is_remake_item(item: dict[str, Any]) -> bool:
    """Purpose: Validate remake item for the delivery-list scanner workflow.

    Effects: This function reads or updates shared application state.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    text = " ".join(str(item.get(key, "")) for key in ("remake", "processState", "queueState")).upper()
    return "REMAKE" in text or re.search(r"\bRM\b", text) is not None


def is_rush_item(item: dict[str, Any]) -> bool:
    """Purpose: Validate rush item for the delivery-list scanner workflow.

    Effects: This function reads or updates shared application state.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    text = " ".join(str(item.get(key, "")) for key in ("remake", "processState", "queueState")).upper()
    return re.search(r"\b(?:SDI|RUSH)\b", text) is not None


def imported_nonpriority_state(value: Any) -> str:
    """Remove operator-owned Rush markers from source-imported state text.

    Rush/SDI is created only through the explicit Priority Work workflow. A+W
    imports may carry descriptive/status text, but they must never create a new
    operator Rush simply because a source field contains one of those tokens.
    Remake markers remain source-authoritative and are intentionally preserved.
    """
    text = str(value or "")
    text = re.sub(r"\b(?:Rush|SDI)\b", " ", text, flags=re.IGNORECASE)
    return re.sub(r"\s{2,}", " ", text).strip(" -|,")


def is_mirror_item(item: dict[str, Any]) -> bool:
    """Purpose: Validate mirror item for the delivery-list scanner workflow.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    text = " ".join(str(item.get(key, "")) for key in ("product", "job", "customer", "route")).upper()
    return "MIRROR" in text or re.search(r"\bMIR\b", text) is not None


def should_print_delivery_item(item: dict[str, Any], exclude_mirrors: bool = True, include_mirror_remakes: bool = True) -> bool:
    """Purpose: Run the should print delivery item workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Converts normalized records into the requested presentation or export format and returns the completed output.
    """
    if not exclude_mirrors:
        return True
    if not is_mirror_item(item):
        return True
    return include_mirror_remakes and is_remake_item(item)


def print_counts_for_items(items: list[dict[str, Any]]) -> dict[str, int]:
    """Purpose: Run the print counts for items workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Converts normalized records into the requested presentation or export format and returns the completed output.
    """
    printable = [item for item in items if should_print_delivery_item(item)]
    return {
        "rowCount": len(printable),
        "pieceCount": sum(int(item.get("qty") or 0) for item in printable),
        "remakeCount": sum(1 for item in printable if is_remake_item(item)),
        "excludedMirrorCount": sum(1 for item in items if is_mirror_item(item) and not should_print_delivery_item(item)),
    }


def row_value(row: Any, key: str, default: Any = "") -> Any:
    """Read a named value from sqlite3.Row, AzureSqlRow, or a dictionary."""

    if isinstance(row, dict):
        return row.get(key, default)
    try:
        return row[key] if key in row.keys() else default
    except (AttributeError, KeyError, TypeError, IndexError):
        return default


def item_from_row(row: sqlite3.Row) -> dict[str, Any]:
    """Purpose: Run the item from row workflow for the delivery-list scanner.

    Effects: This function reads or updates shared application state.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    return {
        "id": row["id"],
        "sourceId": row["source_id"],
        "barcode": row["barcode"],
        "order": row["order_no"],
        "item": row["item_no"],
        "qty": row["qty"],
        "scanned": row["scanned_qty"],
        "dimensions": row["dimensions"],
        "customer": row["customer"],
        "route": row["route"],
        "job": row["job"],
        "product": row["product"],
        # v0.460: keep the imported product verbatim while giving every client a
        # canonical operational glass identity for grouping/reporting.
        "glassType": canonical_clear_glass_label(row["product"] or row["job"] or row["suggested_bay"] or "Other Glass"),
        "processState": row["process_state"],
        "queueState": row["queue_state"],
        "suggestedBay": row["suggested_bay"],
        "priorityDeliveryDate": row_value(row, "priority_delivery_date"),
        "priorityDirectToTruck": bool(row_value(row, "priority_direct_to_truck", 0)),
        "manualOnly": bool(row_value(row, "manual_only", 0)),
        "manualSource": str(row_value(row, "manual_source", "") or ""),
        "protectFromAwImport": bool(row_value(row, "protect_from_aw_import", 0)),
        "rackCode": row["rack_code"] if "rack_code" in row.keys() else "",
        "rackName": row["rack_name"] if "rack_name" in row.keys() else "",
        "rackType": row["rack_type"] if "rack_type" in row.keys() else "",
        "bayCode": row["bay_code"] if "bay_code" in row.keys() else "",
        "lastScannedAt": row["last_scanned_at"] if "last_scanned_at" in row.keys() else "",
        "lastScannedStation": row["last_scanned_station"] if "last_scanned_station" in row.keys() else "",
        "internalRejectCount": int(row_value(row, "internal_reject_count", 0) or 0),
        "lastRejectReason": str(row_value(row, "last_reject_reason", "") or ""),
    }


def event_from_row(row: sqlite3.Row) -> dict[str, Any]:
    """Purpose: Run the event from row workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    item = None
    if row["line_item_id"]:
        item = {
            "id": row["line_item_id"],
            "order": row["order_no"],
            "item": row["item_no"],
            "qty": row["qty"],
            "scanned": row["scanned_qty"],
            "dimensions": row["dimensions"],
            "customer": row["customer"],
            "route": row["route"],
            "job": row["job"],
            "product": row["product"],
            "glassType": canonical_clear_glass_label(row["product"] or row["job"] or row["suggested_bay"] or "Other Glass"),
            "suggestedBay": row["suggested_bay"],
            "rackCode": row_value(row, "rack_code", ""),
            "rackName": row_value(row, "rack_name", ""),
            "rackStatus": row_value(row, "rack_status", ""),
            "lastRackCode": row_value(row, "last_rack_code", ""),
            "lastRackName": row_value(row, "last_rack_name", ""),
            "lastRackType": row_value(row, "last_rack_type", ""),
            "lastRackItemStatus": row_value(row, "last_rack_item_status", ""),
            "bayCode": row_value(row, "bay_code", ""),
            "bayName": row_value(row, "bay_name", ""),
            "lastBayCode": row_value(row, "last_bay_code", ""),
            "lastBayName": row_value(row, "last_bay_name", ""),
            "lastBayAssignmentStatus": row_value(row, "last_bay_assignment_status", ""),
            # v0.352: preserve the physical location that was active when the
            # event happened. All Scans can therefore show Truck 1 on the old
            # scan even after the same glass is later moved to Steel 1.
            "eventRackCode": row_value(row, "event_rack_code", ""),
            "eventRackName": row_value(row, "event_rack_name", ""),
            "eventRackType": row_value(row, "event_rack_type", ""),
            "eventBayCode": row_value(row, "event_bay_code", ""),
            "eventBayName": row_value(row, "event_bay_name", ""),
            "outboundScanned": bool(row_value(row, "outbound_scanned", 0)),
            "listStage": row_value(row, "list_stage", ""),
        }
    rack_move_from = ""
    rack_move_to = ""
    if str(row["event_type"] or "").lower() == "rack_move":
        move_reason = str(row["reason"] or "").strip()
        match = re.match(r"^Moved from (.+?) to (.+)$", move_reason, flags=re.IGNORECASE)
        if match:
            rack_move_from = match.group(1).strip()
            rack_move_to = match.group(2).strip()

    return {
        "ok": row["event_type"] in {"scan", "manual_scan", "undo", "redo", "import", "update", "rack_move"},
        "isManual": row["event_type"] == "manual_scan",
        "barcode": row["canonical_barcode"] or row["barcode"],
        "raw": row["barcode"],
        "item": item,
        "message": row["message"],
        "reason": row["reason"],
        # v0.353: expose the logged source/destination directly. The All Scans
        # Location cell uses the destination for rack_move rows instead of
        # reconstructing direction from rack-history timestamp boundaries.
        "rackMoveFrom": rack_move_from,
        "rackMoveTo": rack_move_to,
        "time": row["created_at"],
        "user": row["user_name"],
        "station": row["station"],
        "eventType": row["event_type"],
        "qtyDelta": row["qty_delta"] if "qty_delta" in row.keys() else 0,
    }


def list_meta(row: sqlite3.Row) -> dict[str, Any]:
    """Purpose: Read meta for the delivery-list scanner workflow.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Applies access and lookup rules, gathers the relevant records, and returns a caller-ready result.
    """
    keys = set(row.keys())
    stage_preset = stage_logic_preset(row["stage"], row["scanner"])
    return {
        "id": row["id"],
        "label": row["label"],
        "deliveryDate": row["delivery_date"],
        "stage": row["stage"],
        "scanner": row["scanner"],
        "stagePreset": stage_preset,
        "stageCategory": STAGE_PRESET_CATALOG.get(stage_preset, {}).get("category", scan_stage_category(row["stage"], row["scanner"])),
        "status": row["status"],
        "revision": row["revision"],
        "updatedAt": str(row["updated_at_utc"] or "") if "updated_at_utc" in keys else "",
    }


def request_user_name(data: dict[str, Any]) -> str:
    """Purpose: Run the request user name workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    return str(data.get("user") or data.get("operator") or "Scanner").strip()[:80]


def request_station(data: dict[str, Any]) -> str:
    """Purpose: Run the request station workflow for the delivery-list scanner.

    Effects: Performs an in-memory calculation and returns data without intentional external side effects.
    Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
    """
    return str(data.get("station") or "").strip()[:80]


def request_scan_quantity(data: dict[str, Any], maximum: int = 999) -> int:
    """Return the validated number of physical pieces represented by one scan action."""
    raw = data.get("scanQty", 1)
    if raw is None or (isinstance(raw, str) and not raw.strip()):
        raw = 1
    try:
        quantity = int(raw)
    except (TypeError, ValueError) as exc:
        raise ValueError("Scan quantity must be a whole number") from exc
    if quantity < 1 or quantity > maximum:
        raise ValueError(f"Scan quantity must be between 1 and {maximum}")
    return quantity


class BaseDeliveryStore:
    database_type = "base"

    def initialize(self) -> None:
        """Purpose: Run the initialize workflow for the delivery-list scanner.

        Effects: Performs an in-memory calculation and returns data without intentional external side effects.
        Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
        """
        raise NotImplementedError

    def health(self) -> dict[str, Any]:
        """Purpose: Run the health workflow for the delivery-list scanner.

        Effects: Performs an in-memory calculation and returns data without intentional external side effects.
        Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
        """
        raise NotImplementedError

    def get_delivery_lists(self, user: dict[str, Any] | None = None) -> list[dict[str, Any]]:
        """Purpose: Read delivery lists for the delivery-list scanner workflow.

        Effects: Performs an in-memory calculation and returns data without intentional external side effects.
        Flow: Applies access and lookup rules, gathers the relevant records, and returns a caller-ready result.
        """
        raise NotImplementedError

    def _rush_move_references(self, con: Any, meta_row: Any, user: dict[str, Any] | None = None) -> list[dict[str, Any]]:
        """Return traceability-only Rush date-move references for the active stage.

        The physical/source line remains owned by its original delivery list. A
        target-date reference is returned separately so the UI can show the order
        on both dates without duplicating quantities, scan state, or rack/bay state.
        """
        if not meta_row:
            return []
        current_list_id = str(row_value(meta_row, "id") or "").strip()
        current_date = str(row_value(meta_row, "delivery_date") or "").strip()
        current_stage = str(row_value(meta_row, "stage") or "").strip()
        current_scanner = str(row_value(meta_row, "scanner") or "").strip()
        if not current_list_id or not current_date:
            return []

        rows = con.execute(
            """
            SELECT li.*,
                   dl.id AS original_list_id,
                   dl.label AS original_list_label,
                   dl.delivery_date AS original_delivery_date,
                   dl.stage AS original_stage,
                   dl.scanner AS original_scanner
            FROM line_items li
            JOIN delivery_lists dl ON dl.id = li.list_id
            WHERE dl.status = 'active'
              AND COALESCE(li.is_deleted, 0) = 0
              AND COALESCE(li.priority_delivery_date, '') <> ''
              AND li.priority_delivery_date <> dl.delivery_date
              AND (dl.id = ? OR li.priority_delivery_date = ?)
            ORDER BY CAST(li.order_no AS INTEGER), CAST(li.item_no AS INTEGER), li.id
            """,
            (current_list_id, current_date),
        ).fetchall()

        references: list[dict[str, Any]] = []
        current_category = scan_stage_category(current_stage, current_scanner)
        for row in rows:
            priority_item = item_from_row(row)
            if not (is_rush_item(priority_item) or is_remake_item(priority_item)):
                continue
            original_list_id = str(row_value(row, "original_list_id") or "").strip()
            original_date = str(row_value(row, "original_delivery_date") or "").strip()
            target_date = str(row_value(row, "priority_delivery_date") or "").strip()
            original_stage = str(row_value(row, "original_stage") or "").strip()
            original_scanner = str(row_value(row, "original_scanner") or "").strip()

            if original_list_id == current_list_id:
                direction = "out"
            elif target_date == current_date:
                # Prefer the corresponding stage/scanner on the target date. If
                # one side has a blank scanner, fall back to the maintained stage
                # category so legacy list labels still resolve correctly.
                exact_stage = original_stage.casefold() == current_stage.casefold()
                exact_scanner = original_scanner.casefold() == current_scanner.casefold()
                same_category = scan_stage_category(original_stage, original_scanner) == current_category
                same_stage = exact_stage and exact_scanner
                if not same_stage and same_category:
                    same_stage = exact_stage or exact_scanner or not original_scanner or not current_scanner
                if not same_stage:
                    continue
                if user is not None and not user_can_access_stage(user, original_stage, original_scanner):
                    continue
                direction = "in"
            else:
                continue

            references.append(
                {
                    "id": f"rush-move:{row['id']}:{direction}",
                    "lineItemId": str(row["id"] or ""),
                    "originalListId": original_list_id,
                    "originalListLabel": str(row_value(row, "original_list_label") or ""),
                    "originalDeliveryDate": original_date,
                    "targetDeliveryDate": target_date,
                    "direction": direction,
                    "order": str(row_value(row, "order_no") or ""),
                    "item": str(row_value(row, "item_no") or ""),
                    "job": str(row_value(row, "job") or ""),
                    "customer": str(row_value(row, "customer") or ""),
                    "product": str(row_value(row, "product") or ""),
                    "dimensions": str(row_value(row, "dimensions") or ""),
                    "sourceId": str(row_value(row, "source_id") or ""),
                    "route": str(row_value(row, "route") or ""),
                    "qty": int(row_value(row, "qty", 0) or 0),
                    "scanned": int(row_value(row, "scanned_qty", 0) or 0),
                    "processState": str(row_value(row, "process_state") or ""),
                    "queueState": str(row_value(row, "queue_state") or ""),
                    "priorityDeliveryDate": target_date,
                }
            )
        if references:
            source_items_by_id: dict[str, dict[str, Any]] = {}
            for source_list_id in sorted({str(reference.get("originalListId") or "") for reference in references if reference.get("originalListId")}):
                for source_item in self._get_line_items(con, source_list_id):
                    source_items_by_id[str(source_item.get("id") or "")] = source_item
            for reference in references:
                source_item = source_items_by_id.get(str(reference.get("lineItemId") or ""), {})
                for key in (
                    "scanned", "rackCode", "rackName", "rackType", "lastRackCode", "lastRackName", "lastRackType",
                    "bayCode", "bayName", "lastBayCode", "lastBayName", "lastScannedAt", "lastScannedStation",
                    "received", "receivedQty", "receivedStage",
                ):
                    if key in source_item:
                        reference[key] = source_item.get(key)
            annotations = self.priority_banner_annotations(con, references)
            for reference in references:
                annotation = annotations.get(str(reference.get("lineItemId") or reference.get("id") or ""))
                if annotation:
                    reference["priorityBanner"] = annotation
        return references
    def get_admin_delivery_list_catalog(
        self,
        page: int = 1,
        query: str = "",
        user: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Return one lightweight Edit Delivery Lists catalog page.

        The Admin list browser should not need the full scanner catalog, per-list
        timing metrics, update-notice summaries, or glass libraries just to paint
        three business weeks. Concrete stores therefore provide a dedicated
        paged catalog for this GUI.
        """
        raise NotImplementedError

    def priority_banner_annotations(self, con: Any, items: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
        """Return active Rush/Remake banner metadata keyed by exact line-item id.

        v0.469 removes Missing Glass Rush as a standalone priority type. Missing
        Glass is now carried as the reason on ordinary Rush, Remake, or combined
        Rush + Remake work. Source-provided RM markers retain their traceable
        fallback reason when no operator audit exists.
        """
        if not items:
            return {}
        ids = [str(item.get("lineItemId") or item.get("id") or "").strip() for item in items]
        ids = [value for value in ids if value]
        latest_by_id: dict[str, dict[str, Any]] = {}
        if ids:
            for offset in range(0, len(ids), 400):
                chunk = ids[offset:offset + 400]
                placeholders = ",".join("?" for _ in chunk)
                rows = con.execute(
                    f"""
                    SELECT id, entity_id, action, reason, payload_json, created_at
                    FROM audit_events
                    WHERE entity_type = 'line_item'
                      AND entity_id IN ({placeholders})
                      AND action IN ('mark_rush_sdi','mark_remake_sdi','clear_rush_priority','clear_rush_remake_sdi')
                    ORDER BY id DESC
                    """,
                    tuple(chunk),
                ).fetchall()
                for row in rows:
                    line_id = str(row_value(row, "entity_id") or "")
                    if line_id in latest_by_id:
                        continue
                    try:
                        payload = json.loads(row_value(row, "payload_json") or "{}")
                    except Exception:
                        payload = {}
                    latest_by_id[line_id] = {
                        "action": str(row_value(row, "action") or ""),
                        "reason": str((payload or {}).get("reason") or row_value(row, "reason") or ""),
                        "responsible": str((payload or {}).get("responsible") or ""),
                        "priorityType": self._priority_work_type((payload or {}).get("orderType") or ""),
                        "unifiedPriorityWork": bool((payload or {}).get("unifiedPriorityWork")),
                        "createdAt": str(row_value(row, "created_at") or ""),
                    }

        intake_requests = [request for request in self._priority_intake_requests_con(con) if request.get("status") == "matched"]
        result: dict[str, dict[str, Any]] = {}
        for item in items:
            line_id = str(item.get("lineItemId") or item.get("id") or "").strip()
            if not line_id:
                continue
            audit = latest_by_id.get(line_id, {})
            action = str(audit.get("action") or "")
            if action in {"mark_rush_sdi", "mark_remake_sdi"}:
                reason = re.sub(r"^\s*(?:Rush|Remake|SDI)\s*-\s*", "", str(audit.get("reason") or ""), flags=re.I).strip()
                # v0.469: unified work records its selected handling type in the
                # existing mark audit. That lets banners survive refresh/import
                # without resurrecting the retired Missing Glass Rush type.
                audit_type = str(audit.get("priorityType") or "").strip()
                if audit.get("unifiedPriorityWork") and audit_type == "Both":
                    result[line_id] = {
                        "kind": "both",
                        "label": "Rush + Remake",
                        "reason": reason or "Priority handling",
                        "responsible": str(audit.get("responsible") or ""),
                        "createdAt": str(audit.get("createdAt") or ""),
                    }
                elif action == "mark_remake_sdi":
                    result[line_id] = {
                        "kind": "remake",
                        "label": "Remake",
                        "reason": reason or "Remake priority handling",
                        "responsible": str(audit.get("responsible") or ""),
                        "createdAt": str(audit.get("createdAt") or ""),
                    }
                else:
                    result[line_id] = {
                        "kind": "rush",
                        "label": "Rush",
                        "reason": reason or "Rush priority handling",
                        "responsible": str(audit.get("responsible") or ""),
                        "createdAt": str(audit.get("createdAt") or ""),
                    }
                continue
            if action in {"clear_rush_priority", "clear_rush_remake_sdi"}:
                continue

            source_key = self.import_order_item_key(item.get("sourceId"), item.get("order"), item.get("item"))
            item_job = self.priority_intake_job_parts(item.get("job"))
            matched_request = next((
                request for request in intake_requests
                if source_key in {str(value) for value in (request.get("matchedSourceKeys") or [])}
                or (
                    item_job.get("normalized")
                    and self.priority_intake_job_parts(request.get("matchedJob")).get("normalized") == item_job.get("normalized")
                )
            ), None)
            if matched_request:
                priority_type = str(matched_request.get("priorityType") or "Rush").title()
                result[line_id] = {
                    "kind": "both" if priority_type == "Both" else ("remake" if priority_type == "Remake" else "rush"),
                    "label": "Rush + Remake" if priority_type == "Both" else priority_type,
                    "reason": str(matched_request.get("reason") or "Priority handling"),
                    "responsible": str(matched_request.get("responsible") or ""),
                    "createdAt": str(matched_request.get("createdAt") or ""),
                }
                continue

            normalized_item = {
                "processState": item.get("processState", ""),
                "queueState": item.get("queueState", ""),
            }
            if is_remake_item(normalized_item):
                result[line_id] = {
                    "kind": "remake",
                    "label": "Remake",
                    "reason": "Imported remake marker",
                    "responsible": "",
                    "createdAt": "",
                }
            elif is_rush_item(normalized_item):
                result[line_id] = {
                    "kind": "rush",
                    "label": "Rush",
                    "reason": "Priority handling",
                    "responsible": "",
                    "createdAt": "",
                }
        return result

    def attach_priority_search_annotations(self, results: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Attach the maintained priority-banner metadata to Smart Search rows."""
        if not results:
            return results
        # Smart Search deliberately shares Delivery List ribbon metadata.
        # v0.469 keeps Missing Glass in the reason while Rush/Remake/Both remain
        # the only priority types, avoiding a second classification path here.
        with self.connect() as con:
            priority_annotations = self.priority_banner_annotations(con, results)
        for result in results:
            annotation = priority_annotations.get(str(result.get("lineItemId") or ""))
            if annotation:
                result["priorityBanner"] = annotation
        return results

