    def canonical_source_change_metrics(self, stage_summaries: list[dict[str, Any]]) -> dict[str, int]:
        """Return one logical delivery-list change total instead of summing stage copies.

        Staging and Outbound intentionally contain the full A+W delivery list, while
        Indian Trail/Greenville/CPU/DTC/custom stages contain operational subsets.
        Summing every stage therefore double-counts one physical piece several times.
        The Airport staging copy is the canonical source-level comparison; Outbound is
        the fallback for historical data that no longer has a staging row.
        """
        rows = [row for row in (stage_summaries or []) if isinstance(row, dict)]
        if not rows:
            return {
                "newPieceQty": 0,
                "updatedPieceQty": 0,
                "addedPieceQty": 0,
                "changedPieceQty": 0,
                "removedLineCount": 0,
                "removedPieceQty": 0,
            }

        def list_id(row: dict[str, Any]) -> str:
            return str(row.get("listId") or "").strip().lower()

        def stage_text(row: dict[str, Any]) -> str:
            return f"{row.get('stage') or ''} {row.get('scanner') or row.get('stageProfile') or ''}".strip().lower()

        preferred = next(
            (row for row in rows if list_id(row).endswith("-staging-airport")),
            None,
        )
        if preferred is None:
            preferred = next(
                (row for row in rows if scan_stage_category(row.get("stage"), row.get("scanner") or row.get("stageProfile")) == "staged"),
                None,
            )
        if preferred is None:
            preferred = next(
                (row for row in rows if list_id(row).endswith("-outbound-airport")),
                None,
            )
        if preferred is None:
            preferred = next(
                (row for row in rows if scan_stage_category(row.get("stage"), row.get("scanner") or row.get("stageProfile")) == "outbound"),
                None,
            )
        if preferred is None:
            preferred = max(
                rows,
                key=lambda row: (
                    int(row.get("totalQty") or 0),
                    int(row.get("originalQty") or 0),
                    int(row.get("changedPieceQty") or 0),
                ),
            )

        return {
            "newPieceQty": int(preferred.get("newPieceQty") or 0),
            "updatedPieceQty": int(preferred.get("updatedPieceQty") or 0),
            "addedPieceQty": int(preferred.get("addedPieceQty") or 0),
            "changedPieceQty": int(preferred.get("changedPieceQty") or 0),
            "removedLineCount": int(preferred.get("removedLineCount") or 0),
            "removedPieceQty": int(preferred.get("removedPieceQty") or 0),
        }

    def normalize_import_change_summary(self, change_summary: dict[str, Any] | None) -> dict[str, Any]:
        """Return import history with physical-piece totals and durable classification.

        Older scanner releases summed Staging, Outbound, and destination-stage
        copies into the import-level piece totals. The stage summaries retain the
        correct facts, so normalize those historical records when they are read.
        A delivery date is considered new only when every created stage belongs to
        a genuinely new date; restored stages and new route stages are updates.
        """
        normalized = dict(change_summary or {})
        stages = [
            dict(row)
            for row in (normalized.get("stages") or normalized.get("stageSummaries") or [])
            if isinstance(row, dict)
        ]
        if not stages:
            return normalized

        normalized.update(self.canonical_source_change_metrics(stages))
        normalized["stages"] = stages

        created_stages = [row for row in stages if bool(row.get("created"))]
        changed_stages = [
            row
            for row in stages
            if bool(row.get("created") or row.get("reactivated"))
            or int(row.get("changedLineCount") or 0)
            or int(row.get("changedPieceQty") or 0)
            or int(row.get("removedLineCount") or 0)
            or int(row.get("removedPieceQty") or 0)
        ]
        created_ids = {str(row.get("listId") or "").strip().lower() for row in created_stages}
        created_staging = any(value.endswith("-staging-airport") for value in created_ids) or any(
            scan_stage_category(row.get("stage"), row.get("scanner") or row.get("stageProfile")) == "staged"
            for row in created_stages
        )
        created_outbound = any(value.endswith("-outbound-airport") for value in created_ids) or any(
            scan_stage_category(row.get("stage"), row.get("scanner") or row.get("stageProfile")) == "outbound"
            for row in created_stages
        )
        inferred_new_date = (
            bool(changed_stages)
            and len(created_stages) == len(changed_stages)
            and created_staging
            and created_outbound
        )
        normalized["newDeliveryList"] = bool(
            normalized.get("newDeliveryList", inferred_new_date)
        )
        normalized["createdCount"] = len(created_stages)
        normalized["reactivatedCount"] = sum(
            1 for row in stages if bool(row.get("reactivated"))
        )
        return normalized

