    @staticmethod
    def global_search_terms(query: str) -> list[str]:
        """Return normalized AND-search terms shared by Smart Search backends.

        v0.451 treats a dimension separator such as ``73 x 64`` as layout
        punctuation instead of a required one-letter token, so size and flag
        terms can be combined naturally in the same search.
        """
        normalized = str(query or "").lower().replace("×", " x ")
        normalized = re.sub(r"(?<=\d)\s*x\s*(?=\d)", " ", normalized)
        tokens = re.findall(r"\d+(?:/\d+)?|[a-z0-9][a-z0-9._/#-]*", normalized)
        aliases = {"rushes": "rush", "remakes": "remake", "flags": "flag"}
        terms: list[str] = []
        for token in tokens:
            token = aliases.get(token, token).strip()
            if not token or token in {"x", "by"}:
                continue
            if token not in terms:
                terms.append(token)
            if len(terms) >= 8:
                break
        return terms

    @staticmethod
    def global_search_sql_terms(terms: list[str]) -> list[str]:
        """Return terms that can safely narrow SQL before flag annotation."""
        priority_terms = {"rush", "remake", "flag", "priority"}
        term_set = set(terms)
        if "missing" in term_set and ("rush" in term_set or "glass" in term_set):
            priority_terms.update({"missing", "glass"})
        return [term for term in terms if term not in priority_terms]

    @staticmethod
    def global_search_result_matches(result: dict[str, Any], terms: list[str]) -> bool:
        """Require every Smart Search term somewhere in one order's metadata."""
        if not terms:
            return True
        banner = result.get("priorityBanner") if isinstance(result.get("priorityBanner"), dict) else {}
        values: list[str] = []
        for key in (
            "order", "item", "sourceId", "barcode", "customer", "job",
            "route", "sourceRoute", "product", "dimensions", "qty", "scanned",
            "deliveryList", "deliveryDate", "priorityDeliveryDate", "stage", "scanner",
            "processState", "queueState", "suggestedBay", "bay", "bayCode", "bayStatus",
            "rackCode", "rackName", "rackType", "rackStatus", "lastScanUser", "locationText",
        ):
            value = result.get(key)
            if value not in (None, ""):
                values.append(str(value))
        values.extend(str(value) for value in (result.get("stageLocations") or []) if value)
        values.extend(str(banner.get(key) or "") for key in ("kind", "label", "reason", "responsible"))
        if result.get("rush"):
            values.extend(("rush", "flag", "priority"))
        if result.get("remake"):
            values.extend(("remake", "flag", "priority"))
        if str(banner.get("kind") or "").lower() == "missing_glass_rush":
            values.extend(("missing", "glass", "rush", "missing glass rush", "flag", "priority"))
        if result.get("directToTruck"):
            values.extend(("direct truck", "direct to truck"))
        corpus = " ".join(values).lower().replace("×", " x ")
        corpus = re.sub(r"(?<=\d)\s*x\s*(?=\d)", " ", corpus)
        return all(term in corpus for term in terms)

    def global_search(self, query: str, user: dict[str, Any] | None = None) -> list[dict[str, Any]]:
        """Purpose: Run the global search workflow for the delivery-list scanner.

        Effects: This function reads or changes database records.
        Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
        """
        clean = str(query or "").strip()
        if len(clean) < 2:
            return []
        like = f"%{clean}%"
        with self.connect() as con:
            rows = con.execute(
                """
                SELECT li.*, dl.stage, dl.scanner, dl.label, dl.delivery_date,
                       b.bay_code,
                       b.display_name AS bay_display_name,
                       ba.status AS bay_status,
                       r.rack_code,
                       r.display_name AS rack_display_name,
                       r.rack_type AS rack_type,
                       r.status AS rack_status,
                       (
                           SELECT se.created_at
                           FROM scan_events se
                           WHERE se.line_item_id = li.id
                             AND se.event_type IN ('scan', 'manual_scan', 'redo')
                             AND se.qty_delta > 0
                           ORDER BY se.id DESC
                           LIMIT 1
                       ) AS last_scan_time,
                       (
                           SELECT se.user_name
                           FROM scan_events se
                           WHERE se.line_item_id = li.id
                             AND se.event_type IN ('scan', 'manual_scan', 'redo')
                             AND se.qty_delta > 0
                           ORDER BY se.id DESC
                           LIMIT 1
                       ) AS last_scan_user
                FROM line_items li
                JOIN delivery_lists dl ON dl.id = li.list_id
                LEFT JOIN bay_assignments ba ON ba.line_item_id = li.id AND ba.status NOT IN ('Cleared', 'Cancelled')
                LEFT JOIN bays b ON b.id = ba.bay_id
                LEFT JOIN rack_items ri ON ri.line_item_id = li.id AND ri.status = 'Active'
                LEFT JOIN racks r ON r.id = ri.rack_id AND r.active = 1
                WHERE dl.status = 'active'
                  AND COALESCE(li.is_deleted, 0) = 0
                  AND (
                       li.order_no LIKE ? OR li.item_no LIKE ? OR li.source_id LIKE ? OR li.barcode LIKE ?
                       OR li.customer LIKE ? OR li.job LIKE ? OR li.route LIKE ?
                       OR li.product LIKE ? OR li.dimensions LIKE ? OR dl.stage LIKE ?
                       OR b.bay_code LIKE ? OR b.display_name LIKE ?
                  )
                ORDER BY dl.delivery_date DESC, CAST(li.order_no AS INTEGER), CAST(li.item_no AS INTEGER)
                LIMIT 100
                """,
                (like, like, like, like, like, like, like, like, like, like, like, like),
            ).fetchall()

        def stage_kind(row: sqlite3.Row) -> str:
            """Resolve search/navigation progress from the configured stage preset.

            Display names may be changed in Stage Editor, so current-state ranking
            must follow the assigned behavior preset rather than English keywords.
            """
            category = scan_stage_category(row["stage"], row["scanner"])
            return {
                "received": "indian_trail",
                "pickup": "cpu",
                "greenville": "greenville",
                "dtc": "dtc",
                "outbound": "outbound",
                "staged": "staging",
            }.get(category, "other")

        def representative_rank(row: sqlite3.Row) -> tuple[int, str, int]:
            """Rank the navigation row by the actual latest scan event.

            A timestamped scan always wins, regardless of process order. Legacy
            scanned rows without event timestamps fall back to process progress.
            Completely unscanned items deliberately choose Staging.
            """
            scanned = int(row["scanned_qty"] or 0)
            kind = stage_kind(row)
            last_scan_time = str(row["last_scan_time"] or "")
            progress_rank = {
                "indian_trail": 100,
                "outbound": 90,
                "cpu": 86,
                "dtc": 84,
                "greenville": 82,
                "staging": 70,
                "other": 40,
            }.get(kind, 0)
            if last_scan_time:
                return (3, last_scan_time, progress_rank)
            if scanned:
                return (2, "", progress_rank)
            if kind == "staging":
                return (1, "", 100)
            if row["bay_code"]:
                return (1, "", 40)
            if row["rack_code"]:
                return (1, "", 30)
            return (0, "", progress_rank)

        def rack_location_label(code: Any) -> str:
            """Purpose: Run the rack location label workflow for the delivery-list scanner.

            Effects: Performs an in-memory calculation and returns data without intentional external side effects.
            Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
            """
            clean_code = normalize_rack_code(str(code or ""))
            if not clean_code:
                return ""
            if clean_code == "T":
                return "Truck 1"
            if re.fullmatch(r"(?:R?T)\d+", clean_code):
                return f"Truck {clean_code[1:]}"
            return f"Rack {clean_code}"

        def airport_label(scanner: Any) -> str:
            """Purpose: Run the airport label workflow for the delivery-list scanner.

            Effects: Performs an in-memory calculation and returns data without intentional external side effects.
            Flow: Normalizes inputs, executes the named responsibility, and returns the result expected by its callers.
            """
            return str(scanner or "Airport Rd").replace(" - ", " ").strip() or "Airport Rd"

        grouped: dict[str, dict[str, Any]] = {}
        for row in rows:
            if user is not None and not user_can_access_stage(user, row["stage"], row["scanner"]):
                continue
            key = f"{row['delivery_date']}::{row['order_no']}::{row['item_no']}"
            rank = representative_rank(row)
            result = grouped.setdefault(key, {
                "lineItemId": row["id"],
                "deliveryListId": row["list_id"],
                "deliveryList": row["label"],
                "deliveryDate": row["delivery_date"],
                "priorityDeliveryDate": str(row_value(row, "priority_delivery_date", "") or ""),
                "stage": row["stage"],
                "scanner": row["scanner"],
                "stagePreset": stage_logic_preset(row["stage"], row["scanner"]),
                "barcode": row["barcode"],
                "sourceId": row["source_id"],
                "order": row["order_no"],
                "item": row["item_no"],
                "qty": row["qty"],
                "scanned": row["scanned_qty"],
                "dimensions": row["dimensions"],
                "customer": row["customer"],
                "job": row["job"],
                "route": row["route"],
                "product": row["product"],
                "processState": row["process_state"],
                "queueState": row["queue_state"],
                "bay": row["bay_display_name"] or row["bay_code"],
                "bayCode": row["bay_code"],
                "bayStatus": row["bay_status"],
                "rackCode": row["rack_code"],
                "rackName": row["rack_display_name"],
                "rackType": row["rack_type"],
                "rackStatus": row["rack_status"],
                "lastScanTime": row["last_scan_time"],
                "lastScanUser": row["last_scan_user"],
                "stageLocations": [],
                "locationText": "Process Not Started",
                "_rank": (0, "", -1),
                "_representativeKind": "",
                "_representativeHasScan": False,
                "_staged": False,
                "_outbound": False,
                "_received": False,
                "_cpu": False,
                "_dtc": False,
                "_greenville": False,
                "_scanner": row["scanner"],
                "_transportCode": "",
                "_bayLabel": "",
                "_preassignedBay": "",
                "_rush": is_rush_item({"processState": row["process_state"], "queueState": row["queue_state"]}),
                "_remake": is_remake_item({"processState": row["process_state"], "queueState": row["queue_state"]}),
            })

            priority_delivery_date = str(row_value(row, "priority_delivery_date", "") or "").strip()
            if priority_delivery_date:
                result["priorityDeliveryDate"] = priority_delivery_date
            result["_rush"] = bool(result.get("_rush")) or is_rush_item({"processState": row["process_state"], "queueState": row["queue_state"]})
            result["_remake"] = bool(result.get("_remake")) or is_remake_item({"processState": row["process_state"], "queueState": row["queue_state"]})

            scanned = int(row["scanned_qty"] or 0)
            kind = stage_kind(row)
            if row["rack_code"] and not result.get("_transportCode"):
                result["_transportCode"] = row["rack_code"]
            if row["bay_code"]:
                bay_label = row["bay_display_name"] or row["bay_code"]
                result["_preassignedBay"] = bay_label
                if scanned and kind == "indian_trail":
                    result["_bayLabel"] = bay_label
            if scanned:
                if kind == "indian_trail":
                    result["_received"] = True
                elif kind == "outbound":
                    result["_outbound"] = True
                elif kind == "cpu":
                    result["_cpu"] = True
                elif kind == "dtc":
                    result["_dtc"] = True
                elif kind == "greenville":
                    result["_greenville"] = True
                elif kind == "staging":
                    result["_staged"] = True
                else:
                    result["_staged"] = True

            if rank >= tuple(result.get("_rank", (0, "", -1))):
                result["deliveryListId"] = row["list_id"]
                result["deliveryList"] = row["label"]
                result["lineItemId"] = row["id"]
                result["stage"] = row["stage"]
                result["scanner"] = row["scanner"]
                result["stagePreset"] = stage_logic_preset(row["stage"], row["scanner"])
                result["scanned"] = row["scanned_qty"]
                result["processState"] = row["process_state"]
                result["queueState"] = row["queue_state"]
                result["bay"] = row["bay_display_name"] or row["bay_code"]
                result["bayCode"] = row["bay_code"]
                result["bayStatus"] = row["bay_status"]
                result["rackCode"] = row["rack_code"] or result.get("_transportCode")
                result["rackName"] = row["rack_display_name"]
                result["rackType"] = row["rack_type"]
                result["rackStatus"] = row["rack_status"]
                result["lastScanTime"] = row["last_scan_time"]
                result["lastScanUser"] = row["last_scan_user"]
                result["_scanner"] = row["scanner"]
                result["_representativeKind"] = kind
                result["_representativeHasScan"] = bool(row["last_scan_time"] or scanned)
                result["_rank"] = rank

        cleaned_results: list[dict[str, Any]] = []
        for result in grouped.values():
            transport_label = rack_location_label(result.get("_transportCode") or result.get("rackCode"))
            bay_label = result.get("_bayLabel") or result.get("bay") or result.get("_preassignedBay")
            representative_kind = str(result.get("_representativeKind") or "")
            representative_has_scan = bool(result.get("_representativeHasScan"))
            if not representative_has_scan:
                location = "Not Scanned Yet"
            elif representative_kind == "indian_trail":
                location = "Indian Trail Received"
                if bay_label:
                    location = f"{location} - Bay {bay_label}"
            elif representative_kind == "outbound":
                location = f"Outbound on {transport_label}" if transport_label else f"Outbound {airport_label(result.get('_scanner'))}"
            elif representative_kind == "staging":
                location = f"Staging {airport_label(result.get('_scanner'))}"
                if transport_label:
                    location = f"{location} on {transport_label}"
            elif representative_kind == "cpu":
                location = "Customer Pickup"
            elif representative_kind == "dtc":
                location = "Delivery to Customer"
            elif representative_kind == "greenville":
                location = "BFS Greenville"
            else:
                location = str(result.get("stage") or result.get("scanner") or "Last scanned stage")

            result["locationText"] = location
            result["stageLocations"] = [location]
            result["rush"] = bool(result.get("_rush"))
            result["remake"] = bool(result.get("_remake"))
            result["navigationDeliveryListId"] = result.get("deliveryListId")
            result["navigationStage"] = result.get("stage")
            if result.get("_transportCode") and not result.get("rackCode"):
                result["rackCode"] = result.get("_transportCode")
            for key in list(result.keys()):
                if key.startswith("_"):
                    result.pop(key, None)
            cleaned_results.append(result)

        # v0.425 compatibility anchor: return cleaned_results[:20]
        return self.attach_priority_search_annotations(cleaned_results)[:20]

    def get_order_detail(self, order_no: str, user: dict[str, Any] | None = None) -> dict[str, Any]:
        """Return one order grouped by physical item with all active stage copies.

        The Order GUI uses this focused payload instead of reusing the much larger
        delivery-list response. Stage copies are retained as history, while each
        physical source item appears once in the main item list.
        """
        clean_order = str(order_no or "").strip()
        if not clean_order:
            raise ValueError("Order number is required")
        with self.connect() as con:
            rows = con.execute(
                """
                SELECT li.*, dl.label AS delivery_list_label, dl.delivery_date, dl.stage, dl.scanner, dl.status AS list_status
                FROM line_items li
                JOIN delivery_lists dl ON dl.id = li.list_id
                WHERE dl.status = 'active'
                  AND COALESCE(li.is_deleted, 0) = 0
                  AND li.order_no = ?
                ORDER BY dl.delivery_date DESC, CAST(li.item_no AS INTEGER), dl.id
                """,
                (clean_order,),
            ).fetchall()
        if user is not None:
            rows = [row for row in rows if user_can_access_stage(user, row["stage"], row["scanner"])]
        if not rows:
            raise ValueError(f"Order {clean_order} was not found in active delivery lists")

        grouped: dict[str, dict[str, Any]] = {}
        for row in rows:
            source_id = str(row["source_id"] or "").strip()
            item_no = str(row["item_no"] or "").strip()
            key = source_id or f"{clean_order}:{item_no}:{row['job'] or ''}"
            item = grouped.setdefault(key, {
                "sourceId": source_id, "order": clean_order, "item": item_no,
                "job": str(row["job"] or ""), "product": str(row["product"] or ""),
                "dimensions": str(row["dimensions"] or ""), "customer": str(row["customer"] or ""),
                "route": str(row["route"] or ""), "qty": int(row["qty"] or 0),
                "processState": str(row["process_state"] or ""), "queueState": str(row["queue_state"] or ""),
                "stages": [],
            })
            item["qty"] = max(int(item.get("qty") or 0), int(row["qty"] or 0))
            for field, column in (("job", "job"), ("product", "product"), ("dimensions", "dimensions"), ("customer", "customer"), ("route", "route")):
                if not item.get(field) and row[column]:
                    item[field] = str(row[column] or "")
            item["stages"].append({
                "listId": str(row["list_id"] or ""),
                "deliveryList": str(row["delivery_list_label"] or ""),
                "deliveryDate": str(row["delivery_date"] or ""),
                "stage": str(row["stage"] or ""),
                "scanner": str(row["scanner"] or ""),
                "scanned": int(row["scanned_qty"] or 0),
                "qty": int(row["qty"] or 0),
            })
        items = sorted(grouped.values(), key=lambda item: (int(re.sub(r"\D+", "", str(item.get("item") or "0")) or 0), str(item.get("item") or "")))
        first = items[0]
        service = getattr(self, "production_files", None)
        if service is not None:
            for item in items:
                item["productionFiles"] = service.item_assets(clean_order, item.get("item"), item.get("job"))
        return {
            "order": clean_order,
            "customer": first.get("customer") or "",
            "job": first.get("job") or "",
            "route": first.get("route") or "",
            "items": items,
            "orderProductionFiles": service.order_assets(clean_order, first.get("job")) if service is not None else {"hardware": [], "sketches": []},
            "productionFileAvailability": service.availability() if service is not None else {},
        }

